WITH matched_keys AS (SELECT id, order_id FROM order_items EXCEPT SELECT id, order_id FROM order_items WHERE quantity = 6), verified AS (SELECT s.* FROM order_items s INNER JOIN matched_keys k ON s.id = k.id AND s.order_id = k.order_id) SELECT s.order_id, s.product_id, s.unit_price, (SELECT MAX(s2.cost) FROM shipments s2 WHERE s2.order_id = s.order_id) AS max_shipment_cost FROM verified s
